select private.rc_release_guide(
  p_slug => 'underwriting-set-up-a-contract',
  p_tool_key => 'underwriting',
  p_title => 'Setting up a contract',
  p_summary => 'Walk a signed order through five steps, from the sponsor and total down to activation.',
  p_screen_keys => array['underwriting.contracts', 'underwriting.contract'],
  p_sort_order => 20,
  p_version_note => 'Optional order numbers, midnight windows, and how an order''s wording becomes lines',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A contract's setup is five steps end to end, taking a signed order from a blank form to something that can actually be scheduled."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Order"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select the underwriter, enter the order number, the sponsorship total, the campaign's run dates, a sponsorship category, and an account rep, with optional notes. Leave the order number blank if the order doesn't print one; the contract then shows “No order number”."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Continue to schedule","marks":[{"type":"bold"}]},{"type":"text","text":" — or, instead of typing everything by hand, upload the signed agreement under “Or start from the signed agreement” and select "},{"type":"text","text":"Create from the agreement","marks":[{"type":"bold"}]},{"type":"text","text":" to have it read from the document. What you've already typed always wins over its reading."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Schedule"}]},{"type":"paragraph","content":[{"type":"text","text":"Add each line from the order — pool or program, days, dates, spot count, and the rest — through the schedule line editor, one at a time. A time window that ends at 12:00 AM runs until midnight. Select "},{"type":"text","text":"Continue to copy","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Copy"}]},{"type":"paragraph","content":[{"type":"text","text":"Link or create the underwriting messages this contract will run, on the Copy step — the same panel the contract's own Copy tab uses later. Select "},{"type":"text","text":"Continue to traffic policy","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Traffic policy"}]},{"type":"paragraph","content":[{"type":"text","text":"Set the total spots on the order, the preemption/makegood policy, whether an affidavit is required, whether makegoods need agency approval, and separation. Select "},{"type":"text","text":"Save policy","marks":[{"type":"bold"}]},{"type":"text","text":", then "},{"type":"text","text":"Continue to review","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Review and activate"}]},{"type":"paragraph","content":[{"type":"text","text":"The contract page shows a “Ready to activate?” checklist against the order, agreement, schedule, copy, and policy, each with a fix-it link if something's missing. Select "},{"type":"text","text":"Activate contract","marks":[{"type":"bold"}]},{"type":"text","text":" once it's clear."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How an order's wording becomes lines"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An instruction that offers a choice stays one line in a pool that covers every choice: “Drive Time” runs in the Drive Time pool (AM or PM Drive), and “either Saturday or Sunday Weekend Edition” in the Weekend Edition pool."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An order that splits its count gets one line per part: “3 per week: 1 Living on Earth, 1 AM/PM Drive, 1 Science Friday” is three lines."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"“Rotating” between two dayparts alternates week by week: two every-other-week lines, the second starting a week after the first."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An instruction that names no pool or program runs anywhere, in Total Program Rotation, narrowed by its days and times."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A product like the Learning Minute is a kind of credit, not a pool: its line keeps the order's day and exact time."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nothing schedules until activation — a draft contract can be edited freely, and can be deleted outright if it turns out not to be needed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"“Create from the agreement” reads a scanned or photographed signed order with one model call; it never invents a sponsor, program, pool, or order number. Anything that isn't a schedule of broadcast credits, such as app or website ads, is listed on the schedule step for you to handle."}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-09-30-underwriting-agreement-reading',
  p_tool_key => 'underwriting',
  p_released_on => '2026-09-30',
  p_title => 'Agreements read the way orders are written',
  p_guide_slugs => array['underwriting-set-up-a-contract', 'underwriting-migrate-legacy-agreements'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Reading a signed agreement now handles the way orders are actually worded: “Drive Time” and “Saturday or Sunday Weekend Edition” become one line in a pool that covers both, “rotating AM/PM Drive” alternates week by week, an instruction with no pool runs anywhere, and a window ending at 12:00 AM runs until midnight. An order that prints no order number is left without one instead of being given a made-up number."}]}]}$body$
);
